UPDATE tb_user_info
SET followee = COALESCE(followee, 0) + 1
WHERE user_id = #{userId}

UPDATE tb_user_info
SET followee = GREATEST(COALESCE(followee, 0) - 1, 0)
WHERE user_id = #{userId}

UPDATE tb_user_info
SET like_count = COALESCE(like_count, 0) + 1
WHERE user_id = #{userId}

UPDATE tb_user_info
SET like_count = GREATEST(COALESCE(like_count, 0) - 1, 0)
WHERE user_id = #{userId}

UPDATE tb_user_info
SET fans = COALESCE(fans, 0) + 1
WHERE user_id = #{userId}

UPDATE tb_user_info
SET fans = GREATEST(COALESCE(fans, 0) - 1, 0)
WHERE user_id = #{userId}
